#!/usr/bin/env python3
"""Expand the compact seed DSL into JSON under data/. Authored data, regenerated by this script."""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, HERE)
from seed_refs import REFS, PAPER_KEYS, CONFIDENCE, VERIFICATION  # noqa: E402
from seed_systems_a import SYSTEMS_A  # noqa: E402
from seed_systems_b import SYSTEMS_B  # noqa: E402
from seed_systems_c import SYSTEMS_C  # noqa: E402

DOMAINS = [
 ("biology", "Biology", "natural", "Living systems, physiology, cells and genes", "cell organism gene enzyme blood neuron hormone tissue protein physiology"),
 ("physics", "Physics", "natural", "Classical physics, circuits, waves and thermal transport", "force energy mass spring circuit voltage current wave heat momentum"),
 ("mechanical_engineering", "Mechanical engineering", "engineered", "Machines, control, fluids, forming and manufacturing", "roller strip rolling gear shaft pump valve press load stress thickness mill motor torque actuator"),
 ("mathematics", "Mathematics", "formal", "Graph theory, optimisation, dynamical systems and probability", "graph network flow optimisation matrix equation probability markov linear"),
 ("chemistry", "Chemistry", "natural", "Reactions, kinetics, equilibria and separation processes", "reaction catalyst concentration reactor acid base kinetics distillation"),
 ("architecture", "Architecture", "engineered", "Buildings, structures, environmental design and circulation", "building truss beam roof ventilation egress facade slab wall"),
 ("economics", "Economics", "social", "Markets, policy, finance and incentives", "price market demand supply inflation bank income investment tax"),
 ("ecology", "Ecology", "natural", "Populations, food webs and ecosystems", "predator prey species population habitat food web nutrient forest lake"),
 ("transportation", "Transportation", "engineered", "Road, rail, air and transit systems", "traffic road vehicle train bus runway queue signal highway"),
 ("energy_systems", "Energy systems", "engineered", "Generation, storage, grids and thermal cycles", "grid generator battery turbine solar power frequency storage reactor"),
 ("computer_science", "Computer science", "formal", "Software, networks, operating systems and architecture", "server packet network cache scheduler request latency thread protocol"),
 ("logistics", "Logistics and supply chains", "social", "Inventory, distribution and production flow", "inventory warehouse supplier shipment order stock kanban hub supply chain"),
]
FAMILY_DISTANCE = {"natural-natural": 0.3, "engineered-engineered": 0.3, "formal-formal": 0.3, "social-social": 0.3,
                   "engineered-natural": 0.6, "engineered-formal": 0.6, "formal-natural": 0.7,
                   "engineered-social": 0.6, "natural-social": 0.9, "formal-social": 0.8}


def parse_system(s):
    nodes = []
    for part in s["nodes"].split(";"):
        nid, label, role = part.split(":")
        nodes.append({"id": nid, "label": label, "kind": "entity", "role": role, "attrs": {}, "provenance": "source",
                      "span": None, "confidence": 1.0})
    edges = []
    for i, part in enumerate(s["edges"].split(";"), 1):
        a, rel, b = part.split(">")
        edges.append({"id": f"e{i}", "source": a, "target": b, "relation": rel, "weight": 1.0,
                      "provenance": "source", "span": None, "confidence": 1.0, "flags": []})
    cons = []
    for i, (kind, desc, tags) in enumerate(s.get("cons", []), 1):
        cons.append({"id": f"c{i}", "description": desc, "kind": kind, "expression": None,
                     "provenance": "source", "tags": tags.split(",")})
    prov = s.get("prov", "sourced")
    scope = ("Supports the description of the underlying system; the graph is an ISOMORPH abstraction." if prov == "sourced"
             else "Background facts only; the specific structure is an ISOMORPH hypothesis, not stated by this source.")
    sources = []
    for key in s["refs"].split(","):
        sources.append({"citation": REFS[key], "kind": "paper" if key in PAPER_KEYS else "textbook",
                        "note": scope, "confidence": CONFIDENCE[key], "verification": VERIFICATION,
                        "claim_scope": "description" if prov == "sourced" else "background_only"})
    return {"id": s["id"], "name": s["name"], "domain": s["domain"], "kind": s.get("kind", "system"),
            "summary": s["summary"], "graph": {"nodes": nodes, "edges": edges},
            "behaviours": s["beh"].split(","), "dynamics": s["dyn"].split(","), "constraints": cons,
            "sources": sources, "provenance_class": prov, "confidence": s.get("conf", "medium"), "limitations": s.get("lim", "Qualitative structural abstraction; not a quantitative model.")}


def main():
    systems = [parse_system(s) for s in SYSTEMS_A + SYSTEMS_B + SYSTEMS_C]
    for sub in ("seed_knowledge", "mechanisms", "domains"):
        os.makedirs(os.path.join(ROOT, "data", sub), exist_ok=True)
    for d, _, _, _, _ in DOMAINS:
        for kind, folder in (("system", "seed_knowledge"), ("mechanism", "mechanisms")):
            items = [s for s in systems if s["domain"] == d and s["kind"] == kind]
            path = os.path.join(ROOT, "data", folder, f"{d}.json")
            if items:
                with open(path, "w") as f:
                    json.dump({"domain": d, "kind": kind, "systems": items}, f, indent=1)
                    f.write("\n")
            elif os.path.exists(path):
                os.remove(path)
    with open(os.path.join(ROOT, "data", "domains", "domains.json"), "w") as f:
        json.dump({"domains": [{"id": i, "name": n, "family": fam, "description": desc, "vocabulary": voc.split()}
                               for i, n, fam, desc, voc in DOMAINS],
                   "family_distance": FAMILY_DISTANCE, "same_domain_distance": 0.0}, f, indent=1)
        f.write("\n")
    print(f"wrote {len(systems)} systems")


if __name__ == "__main__":
    main()
